import{_ as a,o as n,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"指令、上下文与继承","description":"值继承与数组继承的本质区别、add_header 覆盖陷阱，以及 1.29.3 起的 add_header_inherit。","frontmatter":{"title":"指令、上下文与继承","description":"值继承与数组继承的本质区别、add_header 覆盖陷阱，以及 1.29.3 起的 add_header_inherit。","source":"https://daiw.org/manual/nginx/contexts"},"headers":[],"relativePath":"manual/tools/nginx/contexts.md","filePath":"manual/tools/nginx/contexts.md"}'),i={name:"manual/tools/nginx/contexts.md"};function r(l,s,t,d,o,c){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="指令、上下文与继承" tabindex="-1">指令、上下文与继承 <a class="header-anchor" href="#指令、上下文与继承" aria-label="Permalink to &quot;指令、上下文与继承&quot;">​</a></h1><p>这是 nginx 配置<strong>误配率最高</strong>的一章。绝大多数「配了但没生效」都出在继承规则上。</p><h2 id="两种继承语义" tabindex="-1">两种继承语义 <a class="header-anchor" href="#两种继承语义" aria-label="Permalink to &quot;两种继承语义&quot;">​</a></h2><p>nginx 的指令继承分成截然不同的两类：</p><table tabindex="0"><thead><tr><th>类型</th><th>行为</th><th>例子</th></tr></thead><tbody><tr><td><strong>值型</strong></td><td>内层覆盖外层的<strong>那一个值</strong></td><td><code>root</code>、<code>client_max_body_size</code>、<code>keepalive_timeout</code></td></tr><tr><td><strong>数组型</strong></td><td>内层<strong>只要定义了任何一条</strong>，外层的<strong>全部</strong>失效</td><td><code>add_header</code>、<code>proxy_set_header</code>、<code>access_log</code>、<code>gzip_types</code></td></tr></tbody></table><p>值型很直观。<strong>数组型是坑的来源。</strong></p><h2 id="数组型继承-全有或全无" tabindex="-1">数组型继承：全有或全无 <a class="header-anchor" href="#数组型继承-全有或全无" aria-label="Permalink to &quot;数组型继承：全有或全无&quot;">​</a></h2><p><code>add_header</code> 的官方原文：</p><blockquote><p>These directives are inherited from the previous configuration level <strong>if and only if there are no <code>add_header</code> directives defined on the current level</strong>.</p></blockquote><p>「当且仅当当前层级<strong>没有任何</strong> <code>add_header</code>」才继承。翻译成后果：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    add_header X-Frame-Options   SAMEORIGIN;</span></span>
<span class="line"><span>    add_header X-Content-Type-Options nosniff;</span></span>
<span class="line"><span>    add_header Strict-Transport-Security &quot;max-age=31536000&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location /api/ {</span></span>
<span class="line"><span>        add_header X-Api-Version 2;   # ← 只加了这一条</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong><code>/api/</code> 下那三个安全头全部消失</strong>，只剩 <code>X-Api-Version</code>。</p><p>这不是 bug，是明确定义的行为。但它在真实场景里造成过大量安全头缺失——因为「我只是在 location 里加了个头」看起来完全无害。</p><h3 id="传统解法-重复声明" tabindex="-1">传统解法：重复声明 <a class="header-anchor" href="#传统解法-重复声明" aria-label="Permalink to &quot;传统解法：重复声明&quot;">​</a></h3><p>1.29.3 之前唯一的办法是把外层的全部抄进内层：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /api/ {</span></span>
<span class="line"><span>    add_header X-Frame-Options   SAMEORIGIN;</span></span>
<span class="line"><span>    add_header X-Content-Type-Options nosniff;</span></span>
<span class="line"><span>    add_header Strict-Transport-Security &quot;max-age=31536000&quot;;</span></span>
<span class="line"><span>    add_header X-Api-Version 2;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>丑陋且易漏。常见变通是把公共头抽到一个文件用 <code>include</code> 引入每个 location。</p><h3 id="新解法-add-header-inherit-1-29-3-起" tabindex="-1">新解法：add_header_inherit（1.29.3 起） <a class="header-anchor" href="#新解法-add-header-inherit-1-29-3-起" aria-label="Permalink to &quot;新解法：add\\_header\\_inherit（1.29.3 起）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    add_header_inherit on | off | merge;</span></span>
<span class="line"><span>默认:    add_header_inherit on;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>merge</code> 让内层的 <code>add_header</code> <strong>与外层合并</strong>而不是覆盖：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    add_header_inherit merge;          # ← 1.29.3+</span></span>
<span class="line"><span>    add_header X-Frame-Options SAMEORIGIN;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location /api/ {</span></span>
<span class="line"><span>        add_header X-Api-Version 2;    # 现在两个头都有</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这是较新的指令，用前确认版本：<code>nginx -v</code>。低于 1.29.3 时它会导致<strong>启动失败</strong>（unknown directive），而不是被忽略——所以不能用它做「新版生效、旧版降级」的兼容写法。</p><h2 id="proxy-set-header-同理" tabindex="-1">proxy_set_header 同理 <a class="header-anchor" href="#proxy-set-header-同理" aria-label="Permalink to &quot;proxy\\_set\\_header 同理&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    proxy_set_header Host              $host;</span></span>
<span class="line"><span>    proxy_set_header X-Real-IP         $remote_addr;</span></span>
<span class="line"><span>    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location /special/ {</span></span>
<span class="line"><span>        proxy_set_header X-Special 1;   # ← 上面三条全没了</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>后果比 <code>add_header</code> 更严重：上游收不到 <code>Host</code>（会退回 <code>proxy_pass</code> 里的值）与 <code>X-Forwarded-For</code>，可能直接导致上游路由错误或<a href="https://daiw.org/manual/http11/proxy-fields" target="_blank" rel="noreferrer">取不到真实客户端 IP</a>。</p><p><code>proxy_set_header</code> <strong>没有</strong>对应的 <code>_inherit</code> 开关，仍需重复声明或 include。</p><h2 id="上下文层级速查" tabindex="-1">上下文层级速查 <a class="header-anchor" href="#上下文层级速查" aria-label="Permalink to &quot;上下文层级速查&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main</span></span>
<span class="line"><span>├── events                     连接处理方式</span></span>
<span class="line"><span>├── http</span></span>
<span class="line"><span>│   ├── (http 级指令)          全站默认</span></span>
<span class="line"><span>│   ├── upstream               上游组</span></span>
<span class="line"><span>│   ├── map / geo / split_clients</span></span>
<span class="line"><span>│   ├── server</span></span>
<span class="line"><span>│   │   ├── (server 级指令)    单站默认</span></span>
<span class="line"><span>│   │   ├── location</span></span>
<span class="line"><span>│   │   │   ├── (location 级)  单路径</span></span>
<span class="line"><span>│   │   │   ├── location       嵌套 location</span></span>
<span class="line"><span>│   │   │   └── if             ← 有坑，见 rewrite 章</span></span>
<span class="line"><span>│   │   └── if</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── stream                     TCP/UDP，与 http 平级</span></span>
<span class="line"><span>│   ├── upstream</span></span>
<span class="line"><span>│   └── server</span></span>
<span class="line"><span>└── mail</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p><strong><code>stream</code> 与 <code>http</code> 是平级的两套世界</strong>：指令不通用、变量不通用、模块不通用（<code>ngx_stream_proxy_module</code> ≠ <code>ngx_http_proxy_module</code>）。</p><h2 id="「上下文」那一行必须看" tabindex="-1">「上下文」那一行必须看 <a class="header-anchor" href="#「上下文」那一行必须看" aria-label="Permalink to &quot;「上下文」那一行必须看&quot;">​</a></h2><p>官方每条指令的元信息第三行是允许的上下文。举例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    add_header name value [always];</span></span>
<span class="line"><span>上下文:  http, server, location, if in location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>注意 <code>if in location</code> 与 <code>if</code> 是<strong>不同</strong>的上下文标注——前者只允许写在 location 内部的 <code>if</code> 里，不能写在 server 级的 <code>if</code> 里。这类细微差别在文档里是精确的。</p><h2 id="查看最终生效值" tabindex="-1">查看最终生效值 <a class="header-anchor" href="#查看最终生效值" aria-label="Permalink to &quot;查看最终生效值&quot;">​</a></h2><p>推理继承容易出错，直接看展开结果最可靠：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx -T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它输出<strong>所有 include 展开后的完整配置</strong>。想确认某个 location 实际继承到什么，比读源配置靠谱得多。</p><h2 id="一条实践建议" tabindex="-1">一条实践建议 <a class="header-anchor" href="#一条实践建议" aria-label="Permalink to &quot;一条实践建议&quot;">​</a></h2><p>数组型指令<strong>尽量只在一个层级定义</strong>。要么全放 <code>http</code>，要么全放 <code>server</code>，避免跨层级混用。需要分路径差异化时，用 <code>include</code> 把公共部分做成片段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># /etc/nginx/snippets/security-headers.conf</span></span>
<span class="line"><span>add_header X-Frame-Options SAMEORIGIN;</span></span>
<span class="line"><span>add_header X-Content-Type-Options nosniff;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /api/ {</span></span>
<span class="line"><span>    include /etc/nginx/snippets/security-headers.conf;</span></span>
<span class="line"><span>    add_header X-Api-Version 2;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/request-processing">nginx 如何处理请求</a>——server 与 location 的选择规则。</p>`,42)])])}const u=a(i,[["render",r]]);export{h as __pageData,u as default};
